package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"strings"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	line, err := reader.ReadString('\n')
	if err != nil && line == "" {
		fmt.Println("[]")
		return
	}
	line = strings.TrimSpace(line)
	var tokens []string
	if line != "" {
		tokens = strings.Fields(line)
	}
	if tokens == nil {
		tokens = []string{}
	}
	data, _ := json.Marshal(tokens)
	fmt.Println(string(data))
}
